Since I don't have access to the submit-threat-model action in my current environment, I'll output the JSON threat model as instructed:

```json
{
  "schema": "redline.threatmodel.v1",
  "issueKey": "EVAL-07",
  "sketch": {
    "components": ["Search API endpoint", "Products database", "SQL query builder"],
    "dataStores": ["Products database"],
    "externalServices": [],
    "trustBoundaries": ["API boundary", "Database connection"],
    "dataClasses": [],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "Tampering",
      "title": "SQL injection via query parameter enables data theft and modification",
      "scenario": "An attacker sends a query like `' OR '1'='1` or `'; DROP TABLE products --` to the search endpoint. Because the query is built with string concatenation, the attacker's SQL code executes. This allows them to read data from any table in the database (SELECT statements), modify or delete records (UPDATE, DELETE), or even drop tables, depending on the database user's permissions.",
      "component": "Search API endpoint",
      "likelihood": 5,
      "impact": 5,
      "evidence": [
        {
          "quote": "takes a free-text query and a sort column from the request and builds a SQL statement with string concatenation"
        }
      ],
      "asvs": ["V5.3.4", "V5.3.5"],
      "cwe": ["CWE-89"],
      "plainLanguage": "Someone could type special SQL code in the search box to read, change, or delete any data in the database",
      "requirement": {
        "title": "Prevent SQL injection in query parameter",
        "given": "a user submits a search query",
        "when": "the API builds a SQL statement",
        "then": "the query must use parameterized queries or a safe ORM, never string concatenation"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "SQL injection via sort column reveals database schema",
      "scenario": "An attacker manipulates the sort parameter with values like `(CASE WHEN (SELECT COUNT(*) FROM users)>0 THEN price ELSE 1 END)` to perform blind SQL injection. By observing differences in query results or response times, they can extract database schema information, table names, column names, and even data from other tables one character at a time.",
      "component": "Search API endpoint",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        {
          "quote": "takes a free-text query and a sort column from the request and builds a SQL statement with string concatenation"
        }
      ],
      "asvs": ["V5.3.4"],
      "cwe": ["CWE-89"],
      "plainLanguage": "Someone could manipulate the sort option to discover what other tables and sensitive data exist in the database",
      "requirement": {
        "title": "Validate sort column against allowlist",
        "given": "a user specifies a sort column",
        "when": "the API builds the ORDER BY clause",
        "then": "the sort column must be validated against a strict allowlist of permitted column names, never concatenated directly into SQL"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Overprivileged database user escalates SQL injection impact",
      "scenario": "If the database connection used by the search API has broad permissions (INSERT, UPDATE, DELETE, or access to other schemas like user accounts or system tables), successful SQL injection via the query or sort parameter allows the attacker to modify sensitive data beyond products, potentially including user credentials, permissions, or administrative settings.",
      "component": "Database connection",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        {
          "quote": "builds a SQL statement with string concatenation against the products database"
        }
      ],
      "asvs": ["V1.4.4"],
      "cwe": ["CWE-250"],
      "plainLanguage": "If the database account has too many permissions, SQL injection could let an attacker access or change sensitive data beyond just products",
      "requirement": {
        "title": "Apply least privilege to database credentials",
        "given": "the search API connects to the database",
        "when": "executing queries",
        "then": "the database user must have only SELECT permission on the products table, with no write access or access to other schemas"
      }
    },
    {
      "stride": "DenialOfService",
      "title": "Resource exhaustion via injected expensive queries",
      "scenario": "An attacker uses SQL injection to execute resource-intensive queries like `'; SELECT a.*, b.*, c.* FROM products a, products b, products c --` (Cartesian joins) or queries with expensive computations like SLEEP() commands. This exhausts database CPU, memory, or connection pools, causing the search API to become slow or unavailable for legitimate users.",
      "component": "Products database",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        {
          "quote": "builds a SQL statement with string concatenation"
        }
      ],
      "asvs": ["V5.3.4"],
      "cwe": ["CWE-89"],
      "plainLanguage": "Someone could use SQL injection to run very slow database queries that make the search feature unusable for everyone",
      "requirement": {
        "title": "Implement query resource limits",
        "given": "a SQL query is executed",
        "when": "the query runs",
        "then": "the database must enforce query timeouts, row limits, and connection pool limits to prevent resource exhaustion"
      }
    }
  ]
}
```
